/* ─── share links — creation, expiry countdown, management ──────── */
const SHARE_ST = {
  active:   { label: '有效',     cls: 'st-read' },
  expiring: { label: '即将到期', cls: 'st-converting' },
  expired:  { label: '已过期',   cls: 'st-unread' },
  revoked:  { label: '已取消',   cls: 'st-unread' }
};
const SHARES_FILTER = { f: 'all' };
let shareHours = 24;
let cdTimer = null;
const recById = id => shareReg.filter(r => r.id === id)[0];
function shareState(rec) {
  if (!rec) return 'expired';
  if (rec.revoked) return 'revoked';
  if (Date.now() >= rec.exp) return 'expired';
  if (rec.exp - Date.now() < 3600e3) return 'expiring';
  return 'active';
}
function fmtCd(ms) {
  const s = Math.max(0, Math.floor(ms / 1000));
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), ss = s % 60;
  return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0') + ':' + String(ss).padStart(2, '0');
}
function tickCountdowns() {
  let bannerEnded = false, listEnded = false;
  $$('[data-cd]').forEach(el => {
    const exp = +el.dataset.cd || 0; if (!exp) return;
    const rem = exp - Date.now();
    if (rem <= 0) {
      el.textContent = '已过期'; el.classList.add('is-expired');
      if (el.dataset.cdMode === 'share') { bannerEnded = true; el.removeAttribute('data-cd'); }
      else if (el.id === 'shCd') { el.removeAttribute('data-cd'); }
      else listEnded = true;
    } else { el.textContent = fmtCd(rem); el.classList.remove('is-expired'); }
  });
  if (bannerEnded) showShareExpired('expired');
  else if (listEnded && !SHARE.active && state.view === 'shares') renderShares();
}
function startCountdowns() { if (cdTimer) return; cdTimer = setInterval(tickCountdowns, 1000); tickCountdowns(); }
function copyText(text, onOk) {
  const fb = () => {
    const ta = document.createElement('textarea');
    ta.value = text; ta.setAttribute('readonly', '');
    ta.style.position = 'fixed'; ta.style.top = '-1000px'; ta.style.opacity = '0';
    document.body.appendChild(ta); ta.select();
    try { document.execCommand('copy'); if (onOk) onOk(); } catch (e) {}
    document.body.removeChild(ta);
  };
  if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(text).then(() => { if (onOk) onOk(); }).catch(fb);
  else fb();
}
function copyShareLink() {
  const inp = $('#shLink'); if (!inp || !inp.value) return;
  copyText(inp.value, () => { $('#shHint').textContent = '链接已复制，粘贴发给同学即可只读查看。'; toast('分享链接已复制'); });
}
function copyShareLinkFor(rec) {
  if (!rec) return;
  const pl = state.plans.filter(p => p.id === rec.planId)[0];
  if (!pl) { toast('该计划已删除，无法生成链接'); return; }
  copyText(shareLinkFor(pl, rec.id, rec.exp), () => toast('分享链接已复制'));
}
function updateSharePlanPreview(pl) {

function updateSharePlanPreview(pl) {
  if (!pl) return;
  const s = planStats(pl);
  $('#shName').textContent = pl.name;
  $('#shMark').textContent = esc((pl.name || '计').slice(0, 1));
  $('#shMeta').textContent = s.total + ' 篇 · 已精读 ' + s.done + ' · 完成 ' + s.pct + '% · 目标 ' + pl.goal + ' 篇';
}
function setShareHours(h) {
  shareHours = Math.min(24, Math.max(1, +h || 24));
  $$('#shExp button').forEach(b => {
    const on = +b.dataset.hours === shareHours;
    b.classList.toggle('is-on', on);
    b.setAttribute('aria-pressed', on ? 'true' : 'false');
  });
}
function openShareModal(planId, resetId) {
  if (SHARE.active) return;
  const rec = resetId ? recById(resetId) : null;
  const pl = (rec && state.plans.filter(p => p.id === rec.planId)[0]) ||
    (planId && state.plans.filter(p => p.id === planId)[0]) || activePlan();
  $('#shPlan').innerHTML = state.plans.map(p => opt(p.id, p.name, pl.id)).join('');
  $('#shPlanField').hidden = !!rec;
  $('#shLabel').value = rec ? (rec.label || '') : '';
  setShareHours(rec ? (rec.hours || 24) : 24);
  $('#shareModal').dataset.reset = rec ? rec.id : '';
  $('#shareModal').dataset.plan = pl.id;
  $('#shEyebrow').textContent = rec ? '只读分享 · 重置有效期' : '只读分享';
  $('#shTitle').textContent = rec ? '重置分享有效期' : '新建分享链接';
  $('#shSubmit').textContent = rec ? '重置有效期' : '创建分享链接';
  $('#shSubmit').hidden = false;
  $('#shResult').hidden = true;
  $('#shPreview').hidden = true;
  $('#shAgain').hidden = true;
  updateSharePlanPreview(pl);
  $('#shareModal').classList.add('is-open');
  setTimeout(() => { const f = rec ? $('#shLabel') : $('#shPlan'); if (f) f.focus(); }, 30);
}
function closeShareModal() { const m = $('#shareModal'); if (m) m.classList.remove('is-open'); }
function showShareResult(rec, pl) {
  const link = shareLinkFor(pl, rec.id, rec.exp);
  $('#shLink').value = link;
  $('#shPreview').dataset.href = link;
  $('#shCd').dataset.cd = rec.exp;
  $('#shCdBox').classList.toggle('is-warn', rec.exp - Date.now() < 3600e3);
  $('#shResult').hidden = false;
  $('#shHint').textContent = '链接包含该计划的快照数据，较长属正常现象。';
  $('#shSubmit').hidden = true;
  $('#shAgain').hidden = false;
  $('#shPreview').hidden = false;
  startCountdowns();
  setTimeout(() => { const i = $('#shLink'); if (i) { i.focus(); i.select(); } }, 30);
}
function submitShareForm() {
  if (SHARE.active) return;
  const resetId = $('#shareModal').dataset.reset;
  const label = $('#shLabel').value.trim();
  if (resetId) {
    const rec = recById(resetId);
    if (!rec) { closeShareModal(); return; }
    rec.hours = shareHours; rec.exp = Date.now() + shareHours * 3600e3; rec.revoked = false; rec.label = label;
    saveShares();
    const pl = state.plans.filter(p => p.id === rec.planId)[0] || activePlan();
    showShareResult(rec, pl);
    toast('有效期已重置为 ' + shareHours + ' 小时');
  } else {
    const pl = state.plans.filter(p => p.id === $('#shPlan').value)[0] || activePlan();
    const rec = {
      id: 'sh' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
      planId: pl.id, planName: pl.name, label: label,
      created: Date.now(), hours: shareHours, exp: Date.now() + shareHours * 3600e3, revoked: false
    };
    shareReg.push(rec); saveShares();
    showShareResult(rec, pl);
    toast('已创建分享链接 · ' + shareHours + ' 小时内有效');
  }
  renderShell();
  if (state.view === 'shares') renderShares();
}
function revokeShare(id) {
  if (SHARE.active) return;
  const rec = recById(id); if (!rec) return;
  if (!window.confirm('取消这条分享？通过该链接的只读访问将立即失效（仅在本机生效）。')) return;
  rec.revoked = true; saveShares();
  renderShell(); renderShares(); toast('分享已取消');
}
function shareRowHTML(rec) {
  const st = shareState(rec), sm = SHARE_ST[st];
  const pl = state.plans.filter(p => p.id === rec.planId)[0];
  const name = pl ? pl.name : (rec.planName || '已删除的计划');
  const sub = rec.label || ('分享 · ' + rec.id.slice(-6));
  let cdHTML;
  if (st === 'active' || st === 'expiring') {
    cdHTML = '<b class="cd' + (st === 'expiring' ? ' is-warn' : '') + '" data-cd="' + rec.exp + '">' + fmtCd(rec.exp - Date.now()) + '</b>' +
      '<span class="meta">' + rec.hours + ' 小时有效</span>';
  } else {
    cdHTML = '<span class="meta">' + (st === 'revoked' ? '已手动取消' : '有效期已结束') + '</span>';
  }
  const canLink = !!pl;
  return '<tr data-sid="' + rec.id + '">' +
    '<td><div class="u-who"><span class="avatar">' + esc((name[0] || '计').toUpperCase()) + '</span>' +
      '<span><span class="u-name">' + esc(name) + '</span><span class="u-mail">' + esc(sub) + '</span></span></div></td>' +
    '<td><div class="sh-cd-cell">' + cdHTML + '</div></td>' +
    '<td><span class="pill ' + sm.cls + '">' + sm.label + '</span></td>' +
    '<td class="col-hide"><span class="t-year">' + fmtDate(rec.created) + '</span></td>' +
    '<td class="act"><div class="sh-actions">' +
      '<button class="btn btn-ghost' + (canLink ? '' : ' is-off') + '" data-sh-copy="' + rec.id + '">复制</button>' +
      '<button class="btn btn-ghost' + (canLink ? '' : ' is-off') + '" data-sh-preview="' + rec.id + '">预览</button>' +
      '<button class="btn btn-ghost" data-sh-reset="' + rec.id + '">重置有效期</button>' +
      (st === 'revoked' ? '' : '<button class="btn btn-ghost" data-sh-revoke="' + rec.id + '" style="color:var(--danger)">取消分享</button>') +
    '</div></td>' +
  '</tr>';
}
function renderShares() {
  if (SHARE.active) { go('overview'); return; }
  const all = shareReg.slice().sort((a, b) => b.created - a.created);
  const counts = { active: 0, expiring: 0, expired: 0, revoked: 0 };
  all.forEach(r => counts[shareState(r)]++);
  const activeN = counts.active + counts.expiring;
  const chips = [['all', '全部', all.length], ['active', '有效', activeN], ['expired', '已过期', counts.expired], ['revoked', '已取消', counts.revoked]];
  const list = all.filter(r => {
    if (SHARES_FILTER.f === 'all') return true;
    const s = shareState(r);
    if (SHARES_FILTER.f === 'active') return s === 'active' || s === 'expiring';
    return s === SHARES_FILTER.f;
  });
  $('#view').innerHTML =
    '<section class="grid g-4" style="margin-bottom:16px" data-od-id="shares-stats">' +
      tile('有效分享', activeN, '条', '当前可访问的只读链接') +
      tile('即将到期', counts.expiring, '条', '剩余不足 1 小时') +
      tile('已过期', counts.expired, '条', '超过最长 24 小时有效期') +
      tile('已取消', counts.revoked, '条', '手动取消的分享') +
    '</section>' +
    '<section data-od-id="shares-view">' +
      '<div class="sec-head"><div><span class="eyebrow">只读分享</span><h2 class="h2" style="margin-top:6px;font-size:22px">分享链接管理</h2></div>' +
        '<button class="btn btn-primary" id="newShare">' + ICON.plus + ' 新建分享</button></div>' +
      '<div class="lib-toolbar">' +
        chips.map(c => '<button class="chip ' + (SHARES_FILTER.f === c[0] ? 'is-on' : '') + '" data-shfilter="' + c[0] + '">' + c[1] + ' <span class="c">' + c[2] + '</span></button>').join('') +
        '<span class="spacer"></span>' +
        '<span class="meta">链接有效期最长 24 小时，到期后自动失效</span>' +
      '</div>' +
      '<div class="card" style="padding:6px 8px 2px" data-od-id="shares-table">' +
        '<div class="utable-wrap"><table class="ptable">' +
          '<thead><tr><th style="width:32%">分享</th><th>有效期</th><th>状态</th><th class="col-hide">创建</th><th class="act">操作</th></tr></thead>' +
          '<tbody>' + (list.length ? list.map(shareRowHTML).join('')
            : '<tr><td colspan="5"><div class="empty"><p style="margin:0 0 6px">' + (all.length ? '没有匹配的分享' : '还没有分享链接') + '</p><span class="meta">' + (all.length ? '尝试更换筛选条件' : '把某个阅读计划以只读链接分享给同学或导师') + '</span></div></td></tr>') +
          '</tbody>' +
        '</table></div>' +
        '<div class="table-foot"><span class="meta">显示 ' + list.length + ' / ' + all.length + ' 条分享</span><span class="meta">取消与续期仅在创建者本机生效</span></div>' +
      '</div>' +
      '<p class="admin-note">分享数据仅保存在本机浏览器：链接可直接打开只读页，但没有服务端，取消或续期无法同步到已发出的链接。</p>' +
    '</section>';
  $$('#view [data-shfilter]').forEach(b => b.addEventListener('click', () => { SHARES_FILTER.f = b.dataset.shfilter; renderShares(); }));
  const ns = $('#newShare'); if (ns) ns.addEventListener('click', () => openShareModal());
  $$('#view [data-sh-copy]').forEach(b => b.addEventListener('click', () => copyShareLinkFor(recById(b.dataset.shCopy))));
  $$('#view [data-sh-preview]').forEach(b => b.addEventListener('click', () => {
    const rec = recById(b.dataset.shPreview);
    const pl = rec && state.plans.filter(p => p.id === rec.planId)[0];
    if (!pl) { toast('该计划已删除，无法预览'); return; }
    window.open(shareLinkFor(pl, rec.id, rec.exp), '_blank', 'noopener');
  }));
  $$('#view [data-sh-reset]').forEach(b => b.addEventListener('click', () => openShareModal(null, b.dataset.shReset)));
  $$('#view [data-sh-revoke]').forEach(b => b.addEventListener('click', () => revokeShare(b.dataset.shRevoke)));
  startCountdowns();
}
function showShareExpired(reason) {
  if (SHARE.active) return;

/** 分享面板（⑩⑪）—— 实时只读 + 可撤销 + 有有效期。
 *
 * 与术语表一起从旧 `Plan.tsx` 拆出来：这两块是**计划级设置**，
 * 现在挂在「阅读计划」抽屉里（原型也是从计划卡上开分享）。
 */

import { useCallback, useEffect, useState } from 'react'

import { api } from '../api'
import type { Share } from '../types'

/** 到期时间按**小时精度**显示 —— 上限 24 小时，只显示到「日」会让两条链接看起来一样。 */
function fmtTime(iso: string) {
  const d = new Date(iso)
  if (Number.isNaN(d.getTime())) return iso.slice(0, 10)
  const p = (n: number) => String(n).padStart(2, '0')
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`
}

export function SharePanel({ planId, onSwitch }: { planId: number; onSwitch?: () => void }) {
  const [shares, setShares] = useState<Share[]>([])
  const [hours, setHours] = useState('24')
  const [msg, setMsg] = useState('')
  const [err, setErr] = useState('')

  const load = useCallback(async () => {
    if (!planId) return
    try { setShares(await api.shares(planId)) } catch { /* 无权或不存在：不阻塞页面 */ }
  }, [planId])
  useEffect(() => { void load() }, [load])

  async function create() {
    setErr(''); setMsg('')
    try {
      const r = await api.createShare(planId, Number(hours) || 0)
      await navigator.clipboard?.writeText(r.url).catch(() => {})
