/* ── 分享管理 + 有效期倒计时（2026-09-12）────────────────────────────────
   类名与取值逐条对齐原型（`.cd` / `.share-cd` / `.sh-*` / `.share-dead`），
   这样两个仓库的分享管理看起来是同一套东西 —— 而不是"另一版实现"。 */

.cd { font-family: var(--font-mono); font-variant-numeric: tabular-nums; font-size: 12.5px;
  color: var(--fg); letter-spacing: .02em; }
.cd.is-expired, .cd.is-warn { color: var(--danger); }
.share-banner .cd-wrap { display: inline-flex; align-items: center; gap: 6px; color: var(--muted); }
.share-banner .cd-wrap .cd { font-size: 12px; }

.share-cd { display: flex; align-items: center; gap: 9px; padding: 9px 12px;
  border: 1px solid var(--border); border-radius: var(--radius); background: var(--bg); }
.share-cd .cd { font-size: 14px; font-weight: 560; }
.share-cd.is-warn { border-color: color-mix(in oklch, var(--danger) 32%, var(--border)); }
.share-cd .meta { margin-right: auto; }
.share-link-row + .share-cd { margin-top: 8px; }

.share-plan { display: flex; align-items: center; gap: 12px; padding: 13px 15px;
  border: 1px solid var(--border); border-radius: var(--radius-lg); background: var(--bg); }
.share-plan .pc-mark { width: 34px; height: 34px; border-radius: 9px; background: var(--fg-soft);
  color: var(--fg); display: grid; place-items: center; font-family: var(--font-display);
  font-weight: 600; font-size: 16px; flex: none; }
.share-plan .sp-n { font-size: 14px; font-weight: 560; }
.share-link-row { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 8px; }
.share-link-row .input { font-family: var(--font-mono); font-size: 11.5px; }
.flabel { display: block; font-size: 12.5px; font-weight: 540; margin-bottom: 6px; }

/* 分享管理表格：倒计时一列要**窄且不换行**（秒数每秒都在变，换行会抖） */
.sh-cd-cell { display: flex; flex-direction: column; gap: 3px; }
.sh-cd-cell .meta { white-space: nowrap; }
