  async function create() {
    setErr(''); setMsg('')
    try {
      const r = await api.createShare(planId, Number(hours) || 0)
      await navigator.clipboard?.writeText(r.url).catch(() => {})
      setMsg('已创建并复制到剪贴板（浏览器不允许剪贴板时请手动复制）。')
      await load()
